    /**
     * Handles loading a Brand using a UUID
     * @param		UUID uuid 
     * @return		Brand
     */    
    @GetMapping("/load")
    public Brand load( @RequestParam(required=true) UUID uuid ) {    	
    	Brand entity = null;

    	try {  
    		entity = service.getBrand( new BrandFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Brand using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Brand business objects
     * @return		Set<Brand>
     */
    @GetMapping("/")
    public List<Brand> loadAll() {                
    	List<Brand> brandList = null;
        
    	try {
            // load the Brand
            brandList = service.getAllBrand();
            
            if ( brandList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Brands" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Brands ", exc );
        	return null;
        }

        return brandList;
                            
    }

